package com.scavenger;

import com.google.gson.Gson;
import java.io.ByteArrayInputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ItemDatabaseTest
{
	private final Gson gson = new Gson();

	@Test
	public void parsesWellFormedJson()
	{
		String json = "[{\"name\":\"Bucket\",\"itemId\":1925,\"type\":\"GROUND_ITEM\",\"locations\":[{\"x\":1,\"y\":2,\"plane\":0,\"areaLabel\":\"Test\"}]}]";
		InputStream stream = new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8));

		List<ItemSpawn> items = ItemDatabase.parse(gson, stream);

		assertEquals(1, items.size());
		assertEquals("Bucket", items.get(0).name);
		assertEquals(1925, items.get(0).itemId);
		assertFalse(items.get(0).isObject());
		assertEquals(1, items.get(0).locations.get(0).x);
	}

	@Test
	public void parsesObjectTypeSpawn()
	{
		String json = "[{\"name\":\"Cabbage\",\"itemId\":1965,\"type\":\"OBJECT\",\"locations\":[{\"x\":1,\"y\":2,\"plane\":0,\"areaLabel\":\"Test\"}]}]";
		InputStream stream = new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8));

		List<ItemSpawn> items = ItemDatabase.parse(gson, stream);

		assertTrue(items.get(0).isObject());
	}

	@Test
	public void returnsEmptyListForNullStream()
	{
		List<ItemSpawn> items = ItemDatabase.parse(gson, null);

		assertTrue(items.isEmpty());
	}

	@Test
	public void returnsEmptyListForMalformedJson()
	{
		InputStream stream = new ByteArrayInputStream("not json".getBytes(StandardCharsets.UTF_8));

		List<ItemSpawn> items = ItemDatabase.parse(gson, stream);

		assertTrue(items.isEmpty());
	}

	@Test
	public void bundledItemsJsonLoadsAndIsNonEmpty()
	{
		ItemDatabase db = new ItemDatabase(gson);

		assertTrue(db.getAll().size() > 0);
	}

	@Test
	public void parsesLocationRequirementWhenPresent()
	{
		String json = "[{\"name\":\"Blue dragon scale\",\"itemId\":243,\"type\":\"GROUND_ITEM\","
			+ "\"locations\":[{\"x\":1,\"y\":2,\"plane\":0,\"areaLabel\":\"Myths' Guild basement\","
			+ "\"members\":true,\"requirement\":\"Requires completion of Dragon Slayer II\"}]}]";
		InputStream stream = new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8));

		List<ItemSpawn> items = ItemDatabase.parse(gson, stream);

		assertEquals("Requires completion of Dragon Slayer II", items.get(0).locations.get(0).requirement);
	}

	@Test
	public void requirementIsNullWhenAbsentFromJson()
	{
		String json = "[{\"name\":\"Bucket\",\"itemId\":1925,\"type\":\"GROUND_ITEM\",\"locations\":[{\"x\":1,\"y\":2,\"plane\":0,\"areaLabel\":\"Test\"}]}]";
		InputStream stream = new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8));

		List<ItemSpawn> items = ItemDatabase.parse(gson, stream);

		assertNull(items.get(0).locations.get(0).requirement);
	}
}

package com.scavenger;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Font;
import javax.inject.Inject;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.DefaultListCellRenderer;
import javax.swing.DefaultListModel;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.JTextPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import javax.swing.event.ListSelectionListener;
import javax.swing.text.BadLocationException;
import javax.swing.text.SimpleAttributeSet;
import javax.swing.text.StyleConstants;
import javax.swing.text.StyledDocument;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.IconTextField;

class ScavengerPanel extends PluginPanel
{
	private final TargetManager targetManager;
	private final DefaultListModel<ItemSpawn> listModel = new DefaultListModel<>();
	private final Timer refreshTimer;

	private static final String WILDERNESS = "Wilderness";

	private final JTextArea targetName = cardLine(FontManager.getRunescapeBoldFont());
	private final JTextPane targetLocation = richCardLine(FontManager.getRunescapeFont());
	private final JTextArea targetFloor = cardLine(FontManager.getRunescapeFont());
	private final JTextArea requirementText = cardLine(FontManager.getRunescapeFont());

	@Inject
	ScavengerPanel(TargetManager targetManager)
	{
		// unwrapped: lets us own our own JScrollPane and stretch it to fill
		// the sidebar's full height, instead of RuneLite's default NORTH-pinned
		// wrapper that sizes to content only (matches Quest Helper's approach).
		super(false);
		this.targetManager = targetManager;

		setLayout(new BorderLayout(0, 8));
		setBorder(new EmptyBorder(8, 8, 8, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		IconTextField searchField = new IconTextField();
		searchField.setIcon(IconTextField.Icon.SEARCH);
		searchField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchField.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		searchField.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 20, 30));
		// IconTextField doesn't expose its internal JTextField's foreground, so
		// walk the (public) component tree to fix the unreadable default text
		// color instead of leaving it at LAF-default black-on-dark.
		forceTextColor(searchField, Color.WHITE);
		searchField.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				onSearchChanged(searchField.getText());
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				onSearchChanged(searchField.getText());
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				onSearchChanged(searchField.getText());
			}
		});

		JList<ItemSpawn> resultList = new JList<>(listModel);
		resultList.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		resultList.setCellRenderer(new ItemRenderer());
		resultList.addListSelectionListener((ListSelectionListener) e ->
		{
			if (!e.getValueIsAdjusting() && resultList.getSelectedValue() != null)
			{
				targetManager.setActiveItem(resultList.getSelectedValue());
			}
		});

		JButton stopButton = new JButton("Stop Tracking");
		stopButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		stopButton.setForeground(ColorScheme.TEXT_COLOR);
		stopButton.setFocusPainted(false);
		stopButton.addActionListener(e ->
		{
			targetManager.clearActiveItem();
			resultList.clearSelection();
		});

		JLabel searchHeader = sectionHeader("Item Search");

		JPanel searchPanel = new JPanel(new BorderLayout(0, 2));
		searchPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		searchPanel.add(searchHeader, BorderLayout.NORTH);
		searchPanel.add(searchField, BorderLayout.CENTER);

		JScrollPane resultScroll = new JScrollPane(resultList);
		resultScroll.setBorder(null);
		resultScroll.getViewport().setBackground(ColorScheme.DARKER_GRAY_COLOR);
		// Long item names were triggering an unthemed horizontal scrollbar;
		// clip instead of scrolling sideways, matching PluginPanel's own
		// wrapped scroll pane and Quest Helper's result list.
		resultScroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		resultScroll.getVerticalScrollBar().setUnitIncrement(16);

		JPanel top = new JPanel(new BorderLayout(0, 4));
		top.setBackground(ColorScheme.DARK_GRAY_COLOR);
		top.add(searchPanel, BorderLayout.NORTH);
		top.add(resultScroll, BorderLayout.CENTER);

		targetName.setForeground(Color.WHITE);
		targetLocation.setForeground(ColorScheme.TEXT_COLOR);
		targetFloor.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		JPanel targetPanel = card("Target", targetName, targetLocation, targetFloor);

		requirementText.setForeground(ColorScheme.TEXT_COLOR);
		JPanel requirementsPanel = card("Requirements", requirementText);

		JPanel bottom = new JPanel();
		bottom.setLayout(new BoxLayout(bottom, BoxLayout.Y_AXIS));
		bottom.setBackground(ColorScheme.DARK_GRAY_COLOR);
		bottom.add(targetPanel);
		bottom.add(Box.createVerticalStrut(8));
		bottom.add(requirementsPanel);
		bottom.add(Box.createVerticalStrut(8));
		bottom.add(stopButton);

		add(top, BorderLayout.CENTER);
		add(bottom, BorderLayout.SOUTH);

		// ponytail: polling instead of an event subscription — TargetManager's
		// result is recomputed on the client thread every GameTick and this is
		// the simplest way for a Swing component to observe it without wiring
		// its own EventBus subscription just for label text.
		refreshTimer = new Timer(500, e -> updateActiveLabel());
		refreshTimer.start();

		updateActiveLabel();
		onSearchChanged("");
	}

	@Override
	public void addNotify()
	{
		super.addNotify();
		// RuneLite starts plugins (building this panel) before it installs
		// RuneLiteLAF, so descendants like the scrollbar resolve their UI
		// delegate against Swing's Metal default at construction time and
		// never see the real theme. addNotify() only fires once this panel
		// is actually shown, which is guaranteed to be after LAF setup —
		// refresh the whole tree against whatever LAF is active by then.
		SwingUtilities.updateComponentTreeUI(this);
	}

	private static JLabel sectionHeader(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.TEXT_COLOR);
		label.setBorder(new EmptyBorder(0, 0, 2, 0));
		return label;
	}

	private static JPanel card(String title, JComponent... lines)
	{
		JPanel body = new JPanel();
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		body.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.BORDER_COLOR),
			new EmptyBorder(8, 8, 8, 8)));
		for (JComponent line : lines)
		{
			line.setAlignmentX(Component.LEFT_ALIGNMENT);
			body.add(line);
		}

		JPanel wrapper = new JPanel(new BorderLayout(0, 2));
		wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.add(sectionHeader(title), BorderLayout.NORTH);
		wrapper.add(body, BorderLayout.CENTER);
		return wrapper;
	}

	// non-editable, word-wrapping line for use inside a card — JTextArea wraps
	// reliably based on its assigned layout width, unlike JLabel's HTML-CSS
	// width trick which BasicHTML doesn't always honor under BoxLayout.
	private static JTextArea cardLine(Font font)
	{
		JTextArea area = new JTextArea();
		area.setEditable(false);
		area.setFocusable(false);
		area.setOpaque(false);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setFont(font);
		area.setForeground(ColorScheme.TEXT_COLOR);
		area.setBorder(null);
		return area;
	}

	// JTextPane sibling of cardLine()'s JTextArea, used only where a line
	// needs a differently-colored substring (e.g. highlighting "Wilderness")
	// - plain JTextArea can't mix colors within one line.
	private static JTextPane richCardLine(Font font)
	{
		JTextPane pane = new JTextPane();
		pane.setEditable(false);
		pane.setFocusable(false);
		pane.setOpaque(false);
		pane.setFont(font);
		pane.setForeground(ColorScheme.TEXT_COLOR);
		pane.setBorder(null);
		return pane;
	}

	// Renders text into a JTextPane, coloring every occurrence of `highlight`
	// (e.g. "Wilderness") in `highlightColor` and the rest in the pane's
	// normal text color.
	private static void setHighlightedText(JTextPane pane, String text, String highlight, Color highlightColor)
	{
		Font font = pane.getFont();
		SimpleAttributeSet normal = textStyle(font, ColorScheme.TEXT_COLOR);
		SimpleAttributeSet highlighted = textStyle(font, highlightColor);

		StyledDocument doc = pane.getStyledDocument();
		try
		{
			doc.remove(0, doc.getLength());
			int from = 0;
			int idx;
			while ((idx = text.indexOf(highlight, from)) != -1)
			{
				doc.insertString(doc.getLength(), text.substring(from, idx), normal);
				doc.insertString(doc.getLength(), highlight, highlighted);
				from = idx + highlight.length();
			}
			doc.insertString(doc.getLength(), text.substring(from), normal);
		}
		catch (BadLocationException e)
		{
			throw new AssertionError(e);
		}
	}

	private static SimpleAttributeSet textStyle(Font font, Color color)
	{
		SimpleAttributeSet attrs = new SimpleAttributeSet();
		StyleConstants.setForeground(attrs, color);
		StyleConstants.setFontFamily(attrs, font.getFamily());
		StyleConstants.setFontSize(attrs, font.getSize());
		StyleConstants.setBold(attrs, font.isBold());
		return attrs;
	}

	private static void forceTextColor(Container root, Color color)
	{
		for (Component c : root.getComponents())
		{
			if (c instanceof JTextField)
			{
				((JTextField) c).setForeground(color);
				((JTextField) c).setCaretColor(color);
			}
			if (c instanceof Container)
			{
				forceTextColor((Container) c, color);
			}
		}
	}

	private void onSearchChanged(String query)
	{
		// Defer the rebuild: clearing/repopulating the list model synchronously
		// inside insertUpdate blocks the EDT and desyncs the text field's caret.
		SwingUtilities.invokeLater(() ->
		{
			listModel.clear();
			for (ItemSpawn item : targetManager.search(query))
			{
				listModel.addElement(item);
			}
		});
	}

	private void updateActiveLabel()
	{
		ItemSpawn active = targetManager.getActiveItem();
		if (active == null)
		{
			targetName.setText("");
			targetLocation.setText("");
			targetFloor.setText("");
			requirementText.setForeground(ColorScheme.TEXT_COLOR);
			requirementText.setText("");
			return;
		}

		targetName.setText(active.name);

		NearestLocationFinder.Result result = targetManager.getActiveResult();
		if (result == null)
		{
			targetLocation.setText("");
			targetFloor.setText("");
			requirementText.setForeground(ColorScheme.TEXT_COLOR);
			requirementText.setText("");
			return;
		}

		setHighlightedText(targetLocation, "(" + result.location.areaLabel + ")", WILDERNESS, ColorScheme.PROGRESS_ERROR_COLOR);
		targetFloor.setText(result.samePlane ? "" : "- different floor");

		if (result.location.requirement != null)
		{
			requirementText.setForeground(ColorScheme.BRAND_ORANGE);
			requirementText.setText(result.location.requirement);
		}
		else if (result.location.areaLabel.contains(WILDERNESS))
		{
			requirementText.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
			requirementText.setText("Requires entering the Wilderness");
		}
		else
		{
			requirementText.setForeground(ColorScheme.PROGRESS_COMPLETE_COLOR);
			requirementText.setText("No requirements needed.");
		}
	}

	void restart()
	{
		refreshTimer.start();
		updateActiveLabel();
		onSearchChanged("");
	}

	void shutdown()
	{
		refreshTimer.stop();
	}

	private static class ItemRenderer extends DefaultListCellRenderer
	{
		@Override
		public Component getListCellRendererComponent(JList<?> list, Object value, int index,
			boolean isSelected, boolean cellHasFocus)
		{
			JLabel label = (JLabel) super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
			label.setOpaque(true);
			label.setBorder(new EmptyBorder(5, 8, 5, 8));
			label.setBackground(isSelected ? ColorScheme.DARK_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
			label.setForeground(isSelected ? Color.WHITE : ColorScheme.TEXT_COLOR);
			return label;
		}
	}
}

package com.scavenger;

import java.util.List;
import net.runelite.api.coords.WorldPoint;

class NearestLocationFinder
{
	static class Result
	{
		final SpawnLocation location;
		final boolean samePlane;
		final WorldPoint navTarget;

		Result(SpawnLocation location, boolean samePlane, WorldPoint navTarget)
		{
			this.location = location;
			this.samePlane = samePlane;
			this.navTarget = navTarget;
		}
	}

	static Result findNearest(WorldPoint playerLocation, List<SpawnLocation> locations)
	{
		if (locations == null || locations.isEmpty())
		{
			return null;
		}

		SpawnLocation bestSamePlane = null;
		WorldPoint bestSamePlaneTarget = null;
		int bestSamePlaneDist = Integer.MAX_VALUE;
		SpawnLocation bestAnyPlane = null;
		WorldPoint bestAnyPlaneTarget = null;
		int bestAnyPlaneDist = Integer.MAX_VALUE;

		for (SpawnLocation loc : locations)
		{
			// Compare against the entrance (when applicable), not the raw spawn
			// coordinate: OSRS shifts underground instances thousands of tiles
			// away in y, so a cave spawn a short walk from its entrance would
			// otherwise always lose to a genuinely-farther surface alternative.
			WorldPoint target = navTarget(loc, playerLocation);
			int dx = target.getX() - playerLocation.getX();
			int dy = target.getY() - playerLocation.getY();
			int distSq = dx * dx + dy * dy;

			if (distSq < bestAnyPlaneDist)
			{
				bestAnyPlaneDist = distSq;
				bestAnyPlane = loc;
				bestAnyPlaneTarget = target;
			}

			if (loc.plane == playerLocation.getPlane() && distSq < bestSamePlaneDist)
			{
				bestSamePlaneDist = distSq;
				bestSamePlane = loc;
				bestSamePlaneTarget = target;
			}
		}

		if (bestSamePlane != null)
		{
			return new Result(bestSamePlane, true, bestSamePlaneTarget);
		}

		return new Result(bestAnyPlane, false, bestAnyPlaneTarget);
	}

	/**
	 * Where the locator should aim. If the spawn has a curated cave entrance and the
	 * player isn't yet in that spawn's map region, aim at the entrance instead of the
	 * real tile - the real tile is often unreachable in a straight line from outside.
	 */
	private static WorldPoint navTarget(SpawnLocation loc, WorldPoint playerLocation)
	{
		WorldPoint real = new WorldPoint(loc.x, loc.y, loc.plane);
		if (loc.entrance == null || playerLocation.getRegionID() == real.getRegionID())
		{
			return real;
		}

		return new WorldPoint(loc.entrance.x, loc.entrance.y, loc.entrance.plane);
	}
}

package com.scavenger;

import java.awt.Graphics2D;
import java.awt.Shape;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class ScavengerWorldOverlay extends Overlay
{
	private final Client client;
	private final TargetManager targetManager;
	private final ScavengerConfig config;

	@Inject
	ScavengerWorldOverlay(Client client, TargetManager targetManager, ScavengerConfig config)
	{
		this.client = client;
		this.targetManager = targetManager;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(Overlay.PRIORITY_LOW);
	}

	@Override
	public java.awt.Dimension render(Graphics2D graphics)
	{
		NearestLocationFinder.Result result = targetManager.getActiveResult();
		Player player = client.getLocalPlayer();
		if (result == null || player == null)
		{
			return null;
		}

		WorldPoint worldPoint = result.navTarget;
		if (worldPoint.getPlane() != player.getWorldLocation().getPlane())
		{
			return null;
		}

		LocalPoint localPoint = ScavengerCoords.toLocal(client, worldPoint);
		if (localPoint == null)
		{
			return null;
		}

		Tile tile = client.getTopLevelWorldView().getScene().getTiles()[worldPoint.getPlane()][localPoint.getSceneX()][localPoint.getSceneY()];

		// Aiming at the cave entrance rather than the real spawn tile - highlight
		// whatever door/trapdoor/cave-mouth object sits there, same as Quest
		// Helper does for its step objects. There's no ground item to look for at
		// an entrance tile.
		boolean atEntrance = !worldPoint.equals(new WorldPoint(result.location.x, result.location.y, result.location.plane));
		ItemSpawn item = targetManager.getActiveItem();
		Shape highlight;
		if (atEntrance)
		{
			highlight = findEntranceObjectShape(client, worldPoint.getPlane(), localPoint, result.location.entrance.objectId);
		}
		else if (item != null && item.isObject())
		{
			highlight = findObjectShape(tile);
		}
		else
		{
			highlight = findGroundItemShape(client, worldPoint.getPlane(), localPoint, item == null ? -1 : item.itemId);
		}

		if (highlight == null)
		{
			highlight = Perspective.getCanvasTilePoly(client, localPoint);
		}

		if (highlight != null)
		{
			OverlayUtil.renderPolygon(graphics, highlight, config.highlightColor());
		}

		return null;
	}

	// Curated entrance coordinates come from parsing wiki prose (e.g. "a trapdoor
	// by a coffin") rather than exact game data, so they're occasionally off by
	// a tile or two - scan outward in rings from the curated tile for a trapdoor
	// object instead of requiring an exact match, falling back to whatever's on
	// the curated tile itself if nothing trapdoor-shaped is nearby.
	private static final int ENTRANCE_SEARCH_RADIUS = 2;

	private static Shape findEntranceObjectShape(Client client, int plane, LocalPoint localPoint, Integer objectId)
	{
		Tile[][][] planes = client.getTopLevelWorldView().getScene().getTiles();
		Tile[][] tiles = planes[plane];

		for (int ring = 0; ring <= ENTRANCE_SEARCH_RADIUS; ring++)
		{
			for (int dx = -ring; dx <= ring; dx++)
			{
				for (int dy = -ring; dy <= ring; dy++)
				{
					if (Math.max(Math.abs(dx), Math.abs(dy)) != ring)
					{
						continue;
					}

					int x = localPoint.getSceneX() + dx;
					int y = localPoint.getSceneY() + dy;
					if (x < 0 || x >= tiles.length || y < 0 || y >= tiles[x].length)
					{
						continue;
					}

					// Prefer an exact, in-game-verified object id (same approach as
					// Quest Helper's ObjectStep) over the generic trapdoor-name guess -
					// entrances like a volcano's "Rocks" climb-down aren't named
					// anything a name search could safely recognise.
					Shape clickbox = objectId != null
						? findObjectByIdShape(client, tiles[x][y], objectId)
						: findTrapdoorShape(client, tiles[x][y]);
					if (clickbox != null)
					{
						return clickbox;
					}
				}
			}
		}

		return findObjectShape(tiles[localPoint.getSceneX()][localPoint.getSceneY()]);
	}

	private static boolean matchesObjectId(Client client, int candidateId, int wantedId)
	{
		if (candidateId == wantedId)
		{
			return true;
		}

		ObjectComposition comp = client.getObjectDefinition(candidateId);
		if (comp == null || comp.getImpostorIds() == null)
		{
			return false;
		}

		ObjectComposition impostor = comp.getImpostor();
		return impostor != null && impostor.getId() == wantedId;
	}

	private static Shape findObjectByIdShape(Client client, Tile tile, int objectId)
	{
		if (tile == null)
		{
			return null;
		}

		for (GameObject gameObject : tile.getGameObjects())
		{
			if (gameObject != null && matchesObjectId(client, gameObject.getId(), objectId))
			{
				Shape clickbox = gameObject.getClickbox();
				if (clickbox != null)
				{
					return clickbox;
				}
			}
		}

		if (tile.getWallObject() != null && matchesObjectId(client, tile.getWallObject().getId(), objectId))
		{
			Shape clickbox = tile.getWallObject().getClickbox();
			if (clickbox != null)
			{
				return clickbox;
			}
		}

		if (tile.getGroundObject() != null && matchesObjectId(client, tile.getGroundObject().getId(), objectId))
		{
			Shape clickbox = tile.getGroundObject().getClickbox();
			if (clickbox != null)
			{
				return clickbox;
			}
		}

		if (tile.getDecorativeObject() != null && matchesObjectId(client, tile.getDecorativeObject().getId(), objectId))
		{
			Shape clickbox = tile.getDecorativeObject().getClickbox();
			if (clickbox != null)
			{
				return clickbox;
			}
		}

		return null;
	}

	// Trapdoor object ids are re-minted per region (open/closed/locked variants
	// each get their own id), so a hardcoded id list always misses some - match
	// by the object's definition name instead, same as Quest Helper's ObjectStep
	// does for its own generic object matching.
	private static boolean isTrapdoor(Client client, int objectId)
	{
		if (objectId == -1)
		{
			return false;
		}

		ObjectComposition comp = client.getObjectDefinition(objectId);
		if (comp == null)
		{
			return false;
		}

		if ("Trapdoor".equalsIgnoreCase(comp.getName()))
		{
			return true;
		}

		if (comp.getImpostorIds() == null)
		{
			return false;
		}

		ObjectComposition impostor = comp.getImpostor();
		return impostor != null && "Trapdoor".equalsIgnoreCase(impostor.getName());
	}

	private static Shape findTrapdoorShape(Client client, Tile tile)
	{
		if (tile == null)
		{
			return null;
		}

		for (GameObject gameObject : tile.getGameObjects())
		{
			if (gameObject != null && isTrapdoor(client, gameObject.getId()))
			{
				Shape clickbox = gameObject.getClickbox();
				if (clickbox != null)
				{
					return clickbox;
				}
			}
		}

		// Trapdoors are frequently a GroundObject (or WallObject) rather than a
		// plain GameObject - the coffin at Edgeville is the GameObject on its
		// tile, so without this check the loop above finds nothing there.
		if (tile.getWallObject() != null && isTrapdoor(client, tile.getWallObject().getId()))
		{
			Shape clickbox = tile.getWallObject().getClickbox();
			if (clickbox != null)
			{
				return clickbox;
			}
		}

		if (tile.getGroundObject() != null && isTrapdoor(client, tile.getGroundObject().getId()))
		{
			Shape clickbox = tile.getGroundObject().getClickbox();
			if (clickbox != null)
			{
				return clickbox;
			}
		}

		return null;
	}

	private static Shape findObjectShape(Tile tile)
	{
		if (tile == null)
		{
			return null;
		}

		for (GameObject gameObject : tile.getGameObjects())
		{
			if (gameObject != null)
			{
				Shape clickbox = gameObject.getClickbox();
				if (clickbox != null)
				{
					return clickbox;
				}
			}
		}

		if (tile.getWallObject() != null)
		{
			Shape clickbox = tile.getWallObject().getClickbox();
			if (clickbox != null)
			{
				return clickbox;
			}
		}

		if (tile.getDecorativeObject() != null)
		{
			Shape clickbox = tile.getDecorativeObject().getClickbox();
			if (clickbox != null)
			{
				return clickbox;
			}
		}

		if (tile.getGroundObject() != null)
		{
			return tile.getGroundObject().getClickbox();
		}

		return null;
	}

	private static Shape findGroundItemShape(Client client, int plane, LocalPoint localPoint, int itemId)
	{
		LocalPoint found = ScavengerCoords.findGroundItem(client, plane, localPoint, itemId);
		if (found == null)
		{
			return null;
		}

		Tile tile = client.getTopLevelWorldView().getScene().getTiles()[plane][found.getSceneX()][found.getSceneY()];
		int height = tile != null && tile.getItemLayer() != null ? tile.getItemLayer().getHeight() : 0;
		return Perspective.getCanvasTilePoly(client, found, height);
	}
}

package com.scavenger;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Predicate;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.RuneLite;

@Slf4j
@Singleton
class TargetManager
{
	// Troubleshooting log for tracking-mismatch reports - see README's "Help and issues" section.
	// Capped in size so it never grows unbounded on disk.
	private static final Path DEBUG_LOG_FILE = RuneLite.RUNELITE_DIR.toPath().resolve("scavenger").resolve("debug.log");
	private static final long MAX_DEBUG_LOG_BYTES = 200 * 1024;

	private final ItemDatabase itemDatabase;
	private final Client client;
	private final ScavengerConfig config;
	private final ScheduledExecutorService executor;
	private volatile ItemSpawn activeItem;
	private volatile NearestLocationFinder.Result activeResult;

	@Inject
	TargetManager(ItemDatabase itemDatabase, Client client, ScavengerConfig config, ScheduledExecutorService executor)
	{
		this.itemDatabase = itemDatabase;
		this.client = client;
		this.config = config;
		this.executor = executor;
	}

	List<ItemSpawn> search(String query)
	{
		String needle = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
		boolean includeMembers = config.accountType() == AccountType.MEMBERS;
		List<ItemSpawn> results = new ArrayList<>();
		for (ItemSpawn item : itemDatabase.getAll())
		{
			if (!needle.isEmpty() && !item.name.toLowerCase(Locale.ROOT).contains(needle))
			{
				continue;
			}
			if (!item.availableLocations(includeMembers).isEmpty())
			{
				results.add(item);
			}
		}
		return results;
	}

	void setActiveItem(ItemSpawn item)
	{
		this.activeItem = item;
		this.activeResult = null;
	}

	void clearActiveItem()
	{
		this.activeItem = null;
		this.activeResult = null;
	}

	ItemSpawn getActiveItem()
	{
		return activeItem;
	}

	void refresh(WorldPoint playerLocation)
	{
		if (activeItem == null)
		{
			return;
		}

		boolean includeMembers = config.accountType() == AccountType.MEMBERS;
		List<SpawnLocation> candidates = activeItem.availableLocations(includeMembers);
		if (!activeItem.isObject())
		{
			candidates = filterKnownAbsent(candidates, loc -> isGroundItemAbsent(loc, activeItem.itemId));
		}

		activeResult = NearestLocationFinder.findNearest(playerLocation, candidates);
	}

	NearestLocationFinder.Result getActiveResult()
	{
		return activeResult;
	}

	/**
	 * Drops locations the predicate reports as absent, unless that would empty the list -
	 * a location we can't currently see is better than tracking nothing.
	 */
	static List<SpawnLocation> filterKnownAbsent(List<SpawnLocation> locations, Predicate<SpawnLocation> isAbsent)
	{
		List<SpawnLocation> present = new ArrayList<>();
		for (SpawnLocation loc : locations)
		{
			if (!isAbsent.test(loc))
			{
				present.add(loc);
			}
		}
		return present.isEmpty() ? locations : present;
	}

	private boolean isGroundItemAbsent(SpawnLocation loc, int itemId)
	{
		if (client == null)
		{
			return false;
		}

		WorldPoint worldPoint = new WorldPoint(loc.x, loc.y, loc.plane);
		LocalPoint localPoint = ScavengerCoords.toLocal(client, worldPoint);
		if (localPoint == null)
		{
			return false;
		}

		if (ScavengerCoords.findGroundItem(client, loc.plane, localPoint, itemId) != null)
		{
			return false;
		}

		logAbsence(loc, itemId, "no matching ground item within " + ScavengerCoords.GROUND_ITEM_SEARCH_RADIUS + " tiles");
		return true;
	}

	private void logAbsence(SpawnLocation loc, int itemId, String detail)
	{
		String line = String.format("%s wanted id %d absent at %d,%d,%d: %s%n",
			Instant.now(), itemId, loc.x, loc.y, loc.plane, detail);
		executor.execute(() -> appendDebugLine(line));
	}

	// Runs off the client thread - disk IO must never block onGameTick.
	private static void appendDebugLine(String line)
	{
		try
		{
			Files.createDirectories(DEBUG_LOG_FILE.getParent());
			byte[] bytes = line.getBytes(StandardCharsets.UTF_8);
			boolean overSize = Files.exists(DEBUG_LOG_FILE) && Files.size(DEBUG_LOG_FILE) > MAX_DEBUG_LOG_BYTES;
			StandardOpenOption sizeOption = overSize ? StandardOpenOption.TRUNCATE_EXISTING : StandardOpenOption.APPEND;
			Files.write(DEBUG_LOG_FILE, bytes, StandardOpenOption.CREATE, sizeOption);
		}
		catch (IOException e)
		{
			log.debug("scavenger: failed to write debug log", e);
		}
	}
}

package com.scavenger;

import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

/**
 * Converts a curated real-world spawn coordinate into a scene-relative LocalPoint.
 * {@code LocalPoint.fromWorld} alone only does a naive base-offset subtraction, which
 * is wrong inside instanced scenes (many OSRS caves/dungeons are instanced even solo) -
 * it can silently resolve to the wrong tile, or none at all, even when the real target
 * is right next to the player. WorldPoint.toLocalInstance() walks the instance template
 * chunks to find the tile(s) the real-world point actually maps to in the current scene.
 */
final class ScavengerCoords
{
	// Curated ground-item coordinates come from the same wiki-prose scrape as cave
	// entrances and are no more precise - the Deepfin Point "Dwarven stout" pin was off
	// by 2 tiles (curated 1938,2758 vs. the real 1940,2757). Matches ScavengerWorldOverlay's
	// ENTRANCE_SEARCH_RADIUS, which already tolerates the same class of error for entrances.
	static final int GROUND_ITEM_SEARCH_RADIUS = 2;

	private ScavengerCoords()
	{
	}

	static LocalPoint toLocal(Client client, WorldPoint worldPoint)
	{
		WorldView worldView = client.getTopLevelWorldView();
		for (WorldPoint local : WorldPoint.toLocalInstance(worldView, worldPoint))
		{
			LocalPoint localPoint = LocalPoint.fromWorld(worldView, local);
			if (localPoint != null)
			{
				return localPoint;
			}
		}
		return null;
	}

	/**
	 * Ring-searches outward from {@code origin} for a tile carrying {@code itemId} among its
	 * ground items, tolerating a slightly-off curated coordinate instead of requiring an exact
	 * tile match.
	 */
	static LocalPoint findGroundItem(Client client, int plane, LocalPoint origin, int itemId)
	{
		WorldView worldView = client.getTopLevelWorldView();
		Tile[][][] planes = worldView.getScene().getTiles();
		if (plane < 0 || plane >= planes.length)
		{
			return null;
		}
		Tile[][] tiles = planes[plane];

		for (int ring = 0; ring <= GROUND_ITEM_SEARCH_RADIUS; ring++)
		{
			for (int dx = -ring; dx <= ring; dx++)
			{
				for (int dy = -ring; dy <= ring; dy++)
				{
					if (Math.max(Math.abs(dx), Math.abs(dy)) != ring)
					{
						continue;
					}

					int x = origin.getSceneX() + dx;
					int y = origin.getSceneY() + dy;
					if (x < 0 || x >= tiles.length || y < 0 || y >= tiles[x].length)
					{
						continue;
					}

					Tile tile = tiles[x][y];
					if (tile == null)
					{
						continue;
					}

					List<TileItem> groundItems = tile.getGroundItems();
					if (groundItems == null)
					{
						continue;
					}

					for (TileItem tileItem : groundItems)
					{
						if (tileItem.getId() == itemId)
						{
							return LocalPoint.fromScene(x, y, worldView);
						}
					}
				}
			}
		}

		return null;
	}
}

